update public.products set description='Beef Roundabout is cleaned edible beef intestine commonly used as part of Nigerian assorted meat in soups, stews, pepper soup and other thoroughly cooked dishes.', handling_protocols=array['Keep raw intestine completely separate from ready-to-eat foods and produce.','Clean hands, sinks, boards, knives and other equipment thoroughly after handling.','Avoid splashing cleaning water around the kitchen.','Cook thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Beef Roundabout (Oromoro)' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Fresh beef liver is beef offal with a soft texture and rich savoury flavour, suitable for frying, stews, sauces and other thoroughly cooked dishes.', handling_protocols=array['Keep liver cold and separate from ready-to-eat foods.','Do not wash raw liver for food-safety purposes; clean hands, boards, knives and utensils after handling.','Cook thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Beef Liver' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Fresh beef kidney is beef offal used in stews, sauces, assorted-meat preparations and other thoroughly cooked dishes.', handling_protocols=array['Keep raw kidney refrigerated and isolated from produce and cooked foods.','Clean hands and food-contact surfaces after handling and minimise splashing during any cleaning.','Trim as required and cook thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Beef Kidney' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
